const $=id=>document.getElementById(id);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=['Overview','Screen plan','Design lab','Decisions','Patterns'];
// A screen's first field names its place in the app. Each pair is a proposed subview.
const screens=[
['Parent home','Parent · Home','Keep one upcoming visit and one primary action in view.','Next visit','Show the selected dog, service and confirmed time. With no booking, offer Check availability.','Quick access','Open My dogs, Bookings or Messages. Keep household and routine details inside their own tabs.'],
['Luna’s profile','Parent · My dogs','Give each dog a distinct profile that the parent can maintain.','Details','Luna is the existing sample guest. Breed, age and size are parent-entered fields. Golden retriever is sample content.','Capabilities','Record owner-described leash skills, cues and handling preferences. Luna’s actual capabilities are unconfirmed.','Care notes','Separate usual routines from dated instructions. Show whether Leo has seen an update.','Owner','Link to the household profile for contact and handoff preferences.','Messages','Open the parent–Leo conversation with the selected dog in context.','Bookings','See this dog’s upcoming requests and confirmed visits.','Manage dogs','Parents can edit their dog or add another dog from household settings.'],
['Availability & booking','Parent · Bookings','Help a parent find a workable visit before asking for details.','Availability','Select walking or sitting and a date. Show available, unavailable and not yet published as distinct states.','Request','Select dog, service and available time. Review the request before submitting.','Status','Keep requested and confirmed distinct. If a slot changes, return to availability with the dog and service retained.'],
['Leo’s care desk','Leo · Today','Keep the next visit and its most important care change in view.','Scheduled','Show the visit list, selected dog and next care action. Open the full routine on demand.','Care changed','Highlight a dated instruction, with a Mark as seen action and contact shortcut.','Completed','Collapse finished visits and retain the visit update for review.','Empty day','Show no visits scheduled and access to manage availability.'],
['Messages','Parent & Leo · Messages','Keep both sides of the care conversation together.','Inbox','Group conversations by household, with dog or booking context where relevant.','Conversation','Parent and Leo can write and reply. Distinguish an unsent draft from a sent message.','Empty state','Give the parent a way to start a message to Leo and Leo a way to choose a household.'],
['Owner profile','Parent · Settings','Keep household information separate from Luna’s care record.','Contact','Parent-managed name and preferred contact method. Actual contact details are unconfirmed.','Household dogs','Open or edit an existing pet profile and add a dog.','Handoff','Proposed fields for handoff preferences. Confirm visibility and required fields in review.'],
['Services','Parent · Bookings / Leo · Settings','Make dog walking and dog sitting easy to compare.','Walking','Show service scope and available times. Duration, price and coverage are tentative.','Sitting','Show the stay window and care handoff. Confirm overnight policies and pricing with Leo.'],
['Manage availability','Leo · Schedule','Let Leo shape what parents can request.','Edit dates','Set available windows by service and close individual dates.','Conflict','Flag overlap with an existing visit. Ask Leo to resolve the conflict before applying a change.','Parent view','Preview the dates as a parent before publishing availability.']
];
const dims=[
['Card treatment','Soft elevation','Flat surface','shadow','', 'Test whether a subtle shadow makes the pet summary easier to find.'],
['Spacing','Roomy','Compact','','compact','Compare scan speed with a longer list of dogs.'],
['Color direction','Forest & leaf','Forest & sky','','blue','Check whether the accent helps identify the selected dog.'],
['Typography','Sans heading','Serif heading','','serif','Check name recognition and legibility at phone size.'],
['Layout','Horizontal row','Stacked summary','','stack','Compare the portrait and facts at narrow widths.']
];
const patterns=[['Pet identity','Use a portrait or initials, dog name and one relevant detail.','Luna','Sample guest'],['Availability state','Pair each state with a text label. Keep unavailable dates readable.','Available','Unavailable · Not published'],['Visit summary','Use one row for the service, selected dog and booking state.','Dog walking','Luna · Requested'],['Care update','Show the instruction, date range and acknowledgement together.','Temporary care note','Awaiting sitter review'],['Message composer','Keep the recipient visible beside the reply field.','Message Leo','Draft · Sample conversation'],['Empty state','Explain what is missing and give one relevant next step.','No upcoming visits','Check availability']];
const initial=[['Separate parent navigation','UX','Keep dog details, household settings, messages and bookings off the home screen.'],['White space and clean cards','Visual','Use breathing room and omit colored side stripes.'],['Parent-managed dogs','Feature','Parents can update profiles and add another dog.'],['Two-way messaging','Feature','Both the parent and Leo can write messages.'],['Parent-visible availability','Feature','Parents can see available and unavailable times.']].map(([title,type,note],i)=>({id:'known'+i,title,type,note,status:'Approved',by:'Marcos · prior direction'}));
let records;try{records=JSON.parse(localStorage.getItem('leo-design-decisions-v1'))??initial}catch{records=initial}
let screen=0,sub=0,dim=0,filter='All',role='All',map=false;
const btn=(label,action,value='',cls='')=>'<button class="'+cls+'" data-action="'+action+'" data-value="'+escape(value)+'">'+escape(label)+'</button>';
const tag=s=>'<span class="tag '+(s==='In review'?'review':s==='Exploring'?'exploring':'')+'">'+escape(s)+'</span>';
const lead=(title,body)=>'<h1>'+title+'</h1><p class="lead">'+body+'</p>';
function gotoPage(p){location.hash=encodeURIComponent(p);render()}
function tabs(values,active,action){return '<div class="tabs">'+values.map((x,i)=>btn(x,action,i,i===active?'active':'')).join('')+'</div>'}
function queue(){return '<div class="sheet queue">'+screens.slice(0,4).map((s,i)=>'<div class="line"><div><small class="priority">Priority '+(i+1)+'</small><strong>'+s[0]+'</strong></div>'+btn('View plan','screen',i)+'</div>').join('')+'</div>'}
function overview(){return '<div class="hero"><article><span class="eyebrow">Product workspace</span><h1>Design studio</h1><p>Shape the next visit, from the parent’s first booking to Leo’s care notes.</p>'+btn('Explore screen plan','page','Screen plan','primary')+'</article><div class="photo"><img src="../luna-guest.webp" alt="Luna, the sample guest dog"><span class="caption">Luna · Guest profile</span></div></div><div class="section"><h2>Workbench</h2></div><div class="grid">'+[['Design lab','Compare card treatments, spacing and layouts using Luna’s profile.','Compare directions'],['Decisions','Review proposals and record the choices that shape the app.','Open tracker'],['Patterns','Reuse pet cards, care updates and availability states across screens.','Browse patterns']].map(([t,p,a])=>'<article class="card"><h3>'+t+'</h3><p>'+p+'</p>'+btn(a,'page',t)+'</article>').join('')+'</div><div class="section"><h2>Design next</h2><p>Proposed order for the next design pass.</p></div>'+queue()}
function plan(){let s=screens[screen],names=s.filter((_,i)=>i>=3&&i%2===1);return lead('Screen plan','Explore the proposed navigation and open each screen’s details.')+tabs(['Screens','Information architecture'],+map,'map')+(map?'<div class="split">'+[['Parent navigation','Home','My dogs','Bookings','Messages','Settings'],['Leo’s navigation','Today','Schedule','Messages','Settings']].map((a,j)=>'<article class="sheet"><h2>'+a[0]+'</h2>'+a.slice(1).map((v,i)=>'<div class="line"><strong>'+v+'</strong>'+btn(screens[(j?[3,7,4,6]:[0,1,2,4,5])[i]][0],'screen',(j?[3,7,4,6]:[0,1,2,4,5])[i])+'</div>').join('')+'</article>').join('')+'</div>':'<label>Screen <select id="screen">'+screens.map((v,i)=>'<option value="'+i+'" '+(i===screen?'selected':'')+'>'+v[0]+'</option>').join('')+'</select></label><article class="sheet spaced"><span class="eyebrow">'+s[1]+'</span><h2>'+s[0]+'</h2><p>'+s[2]+'</p>'+tabs(names,sub,'sub')+'<div class="previewtab"><h3>'+names[sub]+'</h3><p>'+s[4+2*sub]+'</p></div><div class="actions">'+btn('Propose refinement','propose',s[0]+' / '+names[sub])+'</div></article>')}
function lab(){let d=dims[dim];return lead('Design lab','Compare one visual choice at a time, using the same sample profile.')+tabs(dims.map(v=>v[0]),dim,'dim')+'<p class="lead">'+d[5]+'</p><div class="split">'+[1,2].map(i=>'<article class="sheet"><span class="eyebrow">Option '+(i===1?'A':'B')+'</span><h2>'+d[i]+'</h2><div class="sample '+d[2+i]+'"><div class="line"><img src="../luna-guest.webp" alt=""><div><strong>Luna</strong><div>Golden retriever</div></div></div><small>Guest profile · Sample</small></div>'+btn('Propose this option','propose',d[0]+' · '+d[i])+'</article>').join('')+'</div>'}
function decisions(){let stati=['All','Exploring','In review','Approved'];return lead('Decisions','Record ideas, request a review and approve a specific proposal.')+'<div class="row">'+tabs(stati,stati.indexOf(filter),'filter')+btn('Add proposal','propose','','primary')+'</div><div class="sheet">'+(records.filter(r=>filter==='All'||r.status===filter).map(r=>'<article class="line"><div><small>'+escape(r.type)+'</small><h3>'+escape(r.title)+'</h3><p>'+escape(r.note)+'</p>'+tag(r.status)+(r.by?' <small>'+escape(r.by)+'</small>':'')+'</div><div class="actions">'+(r.status==='Approved'?btn('Propose revision','propose',r.title):r.status==='Exploring'?btn('Edit proposal','edit',r.id)+btn('Request review','request',r.id):btn('Return to exploration','return',r.id)+btn('Review decision','review',r.id,'primary'))+'</div></article>').join('')||'<p>No decisions in this stage.</p>')+'</div>'}
function patternView(){return lead('UI patterns','Proposed building blocks for the parent app and Leo’s care desk.')+'<div class="grid">'+patterns.map(([t,p,a,b])=>'<article class="card"><h3>'+t+'</h3><p>'+p+'</p><div class="previewtab"><b>'+a+'</b><div>'+b+'</div></div>'+btn('Refine pattern','propose',t)+'</article>').join('')+'</div>'}
function render(){let page;try{page=decodeURIComponent(location.hash.slice(1))}catch{}if(!pages.includes(page))page='Overview';$('nav').innerHTML=pages.map(p=>'<button aria-current="'+(p===page)+'" data-action="page" data-value="'+p+'">'+p+'</button>').join('');$('view').innerHTML=({Overview:overview,'Screen plan':plan,'Design lab':lab,Decisions:decisions,Patterns:patternView})[page]()}
function save(){try{localStorage.setItem('leo-design-decisions-v1',JSON.stringify(records))}catch{$('notice').textContent='Browser storage unavailable. Changes are temporary.'}render()}
const dialog=document.querySelector('dialog');let commit;
function modal(title,fields,label,fn){$('modal-title').textContent=title;$('fields').innerHTML=fields;$('submit').textContent=label;commit=fn;dialog.showModal()}
function proposal(title='',r){let types=['UX','Visual','Copy','Feature'];modal(r?'Edit proposal':'New proposal','<label>Decision<input name="title" required maxlength="140" value="'+escape(title)+'"></label><label>Area <select name="type">'+types.map(t=>'<option '+((r?.type??(pages[2]===decodeURIComponent(location.hash.slice(1))?'Visual':'UX'))===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Proposed change and rationale<textarea name="note" required maxlength="2000">'+escape(r?.note??'')+'</textarea></label>','Save for exploration',data=>{let fields={title:data.get('title').trim(),type:data.get('type'),note:data.get('note').trim()};if(!fields.title||!fields.note)return false;if(r)Object.assign(r,fields);else records.unshift({...fields,id:crypto.randomUUID(),status:'Exploring'});filter='Exploring';gotoPage('Decisions')})}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let {action:a,value:v}=el.dataset,r=records.find(x=>x.id===v);switch(a){case'page':gotoPage(v);break;case'screen':screen=+v;sub=0;map=false;gotoPage('Screen plan');break;case'map':map=!!+v;break;case'sub':sub=+v;break;case'dim':dim=+v;break;case'filter':filter=['All','Exploring','In review','Approved'][+v];break;case'propose':proposal(v);return;case'edit':proposal(r.title,r);return;case'request':r.status='In review';filter='In review';save();break;case'return':r.status='Exploring';filter='Exploring';save();break;case'review':modal('Human review','<h3 class="spaced">'+escape(r.title)+'</h3><p>'+escape(r.note)+'</p><label>Reviewer name<input name="reviewer" required maxlength="80"></label><label><input type="checkbox" required> I reviewed this proposal and approve this decision.</label>','Approve decision',data=>{let by=data.get('reviewer').trim();if(!by)return false;r.by=by+' · '+new Date().toLocaleDateString();r.status='Approved';filter='Approved'});return}render()});
document.addEventListener('change',e=>{if(e.target.id==='screen'){screen=+e.target.value;sub=0;render()}});
$('form').onsubmit=e=>{e.preventDefault();if(commit(new FormData(e.target))===false)return;dialog.close();save()};$('cancel').onclick=()=>dialog.close();window.addEventListener('hashchange',render);render();
